+        let mut last_mapping_end = self.range.start;
+
+        for mapping in self.iter() {
+            if last_mapping_end < mapping.map_to_addr() {
+                return false;
+            }
+            last_mapping_end = mapping.map_end();
+        }
+
+        if last_mapping_end < self.range.end {
+            return false;
+        }
+
+        true
+    }
