31:         for (vm_mapping_range, vm_mapping_perms) in protect_mappings {
32:             if last_mapping_end < vm_mapping_range.start {
33:                 return_errno_with_message!(
34:                     Errno::ENOMEM,
35:                     "the range contains pages that are not mapped"
36:                 );
